#include <bits/stdc++.h>
using namespace std;

struct Osoba { string imie; int wiek; };

int main() {
    vector<int> a = {5, 3, 5, 1};
    sort(a.begin(), a.end(), [](int x, int y) { return x > y; });   // malejąco: >, NIE >=

    vector<Osoba> o = {{"Ala", 15}, {"Ola", 14}, {"Ela", 15}};
    sort(o.begin(), o.end(), [](const Osoba& p, const Osoba& q) {
        if (p.wiek != q.wiek) return p.wiek < q.wiek;   // najpierw wiek rosnąco
        return p.imie < q.imie;                          // przy remisie imię
    });
    for (auto& x : o) cout << x.imie << ' ' << x.wiek << '\n';

    // set z komparatorem tylko po wieku: Ala i Ela są "równe" -> jedna znika!
    auto cmpWiek = [](const Osoba& p, const Osoba& q) { return p.wiek < q.wiek; };
    set<Osoba, decltype(cmpWiek)> s(cmpWiek);
    for (auto& x : o) s.insert(x);
    cout << s.size() << '\n';   // 2, nie 3
}

